describe('Preparation interruptions and write acknowledgement',()=>{
 const reachSeal=async()=>{vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,17));await mount();field('Your moment','Team dinner today at 7:30 PM');click('Review my moment');click('Continue');click('Review & seal');};
 const pressSeal=()=>act(()=>(host.querySelector('[aria-label="Hold to seal"]') as HTMLElement).dispatchEvent(new MouseEvent('mousedown',{bubbles:true,button:0})));
 it.each(['inactive','background'] as const)('cancels a hold on %s and preserves the reviewed draft for an explicit retry',async(state)=>{let notify:(state:AppStateStatus)=>void=()=>{};vi.spyOn(AppState,'addEventListener').mockImplementation((_event,handler)=>{notify=handler as typeof notify;return{remove:vi.fn()};});await reachSeal();pressSeal();act(()=>vi.advanceTimersByTime(600));act(()=>notify(state));await act(async()=>vi.advanceTimersByTime(1400));expect(h.commit).not.toHaveBeenCalled();expect(host.textContent).toContain('Only what you approve');act(()=>document.dispatchEvent(new MouseEvent('mouseup',{bubbles:true,button:0})));act(()=>notify('active'));pressSeal();await act(async()=>vi.advanceTimersByTime(1400));expect(h.commit).toHaveBeenCalledTimes(1);expect(h.moments[0]?.title).toContain('Team dinner');expect(host.textContent).toContain('Go perform.');});
 it('does not save an unfinished hold after leaving the screen',async()=>{await reachSeal();pressSeal();act(()=>vi.advanceTimersByTime(600));act(()=>root.unmount());root=createRoot(host);await act(async()=>vi.advanceTimersByTime(1400));expect(h.commit).not.toHaveBeenCalled();expect(h.moments).toHaveLength(0);});
 it('keeps a failed Seal review retryable with the same transaction and one saved Moment',async()=>{await reachSeal();h.commit.mockRejectedValueOnce(new Error('storage unavailable'));pressSeal();await act(async()=>vi.advanceTimersByTime(1400));expect(host.textContent).toContain('Not sealed yet');expect(h.moments).toHaveLength(0);expect(host.textContent).not.toContain('Go perform.');const failed=h.commit.mock.calls[0]![0] as Moment;act(()=>document.dispatchEvent(new MouseEvent('mouseup',{bubbles:true,button:0})));pressSeal();await act(async()=>vi.advanceTimersByTime(1400));expect(h.commit).toHaveBeenCalledTimes(2);expect(h.commit.mock.calls[1]![0].preparation.transactionId).toBe(failed.preparation!.transactionId);expect(h.moments).toHaveLength(1);expect(host.textContent).toContain('Go perform.');});
 it('shows saving and blocks a second approval until the write is acknowledged',async()=>{await reachSeal();let release!:()=>void;h.commit.mockImplementationOnce(()=>new Promise<void>(resolve=>{release=resolve;}));pressSeal();await act(async()=>vi.advanceTimersByTime(1400));expect(host.textContent).toContain('Saving…');const seal=host.querySelector('[aria-label="Hold to seal"]') as HTMLElement;expect(seal.getAttribute('aria-disabled')).toBe('true');expect(seal.getAttribute('aria-busy')).toBe('true');expect(h.moments).toHaveLength(0);expect(host.textContent).not.toContain('Go perform.');act(()=>seal.dispatchEvent(new MouseEvent('mousedown',{bubbles:true,button:0})));await act(async()=>vi.advanceTimersByTime(1400));expect(h.commit).toHaveBeenCalledTimes(1);await act(async()=>release());expect(h.moments).toHaveLength(1);expect(host.textContent).toContain('Go perform.');});
 it('does not announce a Return that failed to save, and permits retry',async()=>{const m=existing();m.preparation!.lockedInAtIso=new Date().toISOString();h.moments=[m];h.params={momentId:m.id};await mount();click('Heading back?');h.commit.mockRejectedValueOnce(new Error('offline disk'));await act(async()=>button('Made it back ✓').click());expect(host.textContent).toContain('Could not save that change');expect(host.textContent).not.toContain('Did it go the way you wanted?');expect(h.moments[0]!.preparation!.returnedAtIso).toBeUndefined();await act(async()=>button('Made it back ✓').click());expect(h.moments[0]!.preparation!.returnedAtIso).toBeTruthy();expect(host.textContent).toContain('Did it go the way you wanted?');expect(h.moments).toHaveLength(1);});
});

