 const pendingSeal=async()=>{vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,19,59,58));const m=existing();delete m.preparation;m.startAtIso=new Date(2027,0,8,18).toISOString();m.endAtIso=new Date(2027,0,8,20).toISOString();h.moments=[m];h.params={momentId:m.id};await mount();await act(async()=>button('Prepare').click());act(()=>(host.querySelector('[aria-label="Edit date and time"]') as HTMLElement).click());click('This is happening now');click('Continue');click('Review & seal');};
