describe('Calendar revisions require current visible review',()=>{
 const setupCalendar=()=>{vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,17));const m=existing();delete m.preparation;m.source='calendar';m.calendarEventId='source';m.startAtIso=new Date(2027,0,8,19,30).toISOString();m.endAtIso=new Date(2027,0,8,21).toISOString();h.calendar=[m];h.params={momentId:m.id};return m;};
 it('preserves edits until an explicit update review, then Seals only the updated source fields',async()=>{const m=setupCalendar();await mount();await act(async()=>button('Prepare').click());field('Moment','My edited dinner');const changed={...m,title:'Moved dinner',startAtIso:new Date(2027,0,9,20).toISOString(),endAtIso:new Date(2027,0,9,22).toISOString()};h.calendar=[changed];await mount();expect((host.querySelector('[aria-label="Moment"]') as HTMLInputElement).value).toBe('My edited dinner');expect(button('Continue').getAttribute('aria-disabled')).toBe('true');click('Continue');expect(host.textContent).not.toContain('YOUR PLAN · NOT SEALED YET');click('Review updated event');expect((host.querySelector('[aria-label="Moment"]') as HTMLInputElement).value).toBe('Moved dinner');expect((host.querySelector('[aria-label="Date · YYYY-MM-DD"]') as HTMLInputElement).value).toBe('2027-01-09');expect((host.querySelector('[aria-label="Time · HH:mm"]') as HTMLInputElement).value).toBe('20:00');expect(h.commit).not.toHaveBeenCalled();click('Continue');click('Review & seal');act(()=>(host.querySelector('[aria-label="Hold to seal"]') as HTMLElement).dispatchEvent(new MouseEvent('mousedown',{bubbles:true,button:0})));await act(async()=>vi.advanceTimersByTime(1400));expect(h.moments[0]!.title).toBe(changed.title);expect(h.moments[0]!.startAtIso).toBe(changed.startAtIso);expect(h.moments[0]!.calendarSource?.startAtIso).toBe(changed.startAtIso);expect(h.calendar).toEqual([changed]);});
 it('updates an unaccepted proposal without advancing it automatically',async()=>{const m=setupCalendar();await mount();h.calendar=[{...m,title:'Updated proposal'}];await mount();expect(host.textContent).toContain('Updated proposal?');expect(button('Prepare')).toBeTruthy();expect(host.querySelector('[aria-label="Moment"]')).toBeNull();expect(h.commit).not.toHaveBeenCalled();});
 it('requires updated review if the source changed while Prepare was awaiting acknowledgement',async()=>{const m=setupCalendar();h.params.proposal='1';await mount();let release!:()=>void;h.preference.mockImplementationOnce(()=>new Promise<void>(resolve=>{release=resolve;}));act(()=>button('Prepare').click());h.calendar=[{...m,title:'Changed while waiting'}];await mount();await act(async()=>release());expect(host.textContent).toContain('Review updated event');expect(button('Continue').getAttribute('aria-disabled')).toBe('true');expect(h.commit).not.toHaveBeenCalled();click('Review updated event');expect((host.querySelector('[aria-label="Moment"]') as HTMLInputElement).value).toBe('Changed while waiting');});
 it('does not revive a source whose revised end is already past',async()=>{const m=setupCalendar();await mount();await act(async()=>button('Prepare').click());h.calendar=[{...m,startAtIso:new Date(2027,0,8,15).toISOString(),endAtIso:new Date(2027,0,8,16).toISOString()}];await mount();expect(host.textContent).toContain('That Moment has ended');expect(host.querySelector('[aria-label="Moment"]')).toBeNull();expect(h.commit).not.toHaveBeenCalled();});
 it('drops a changed source entirely when access is revoked',async()=>{const m=setupCalendar();await mount();await act(async()=>button('Prepare').click());h.calendar=[{...m,title:'New source title'}];await mount();h.calendar=[];await mount();expect(host.textContent).not.toContain('New source title');expect(host.textContent).not.toContain('Review updated event');expect(host.textContent).toContain('no longer available');expect(h.commit).not.toHaveBeenCalled();});
});

describe('Updated calendar end times replace the old candidate deadline',()=>{
 it.each([{hour:18,afterMs:3600001,expired:true},{hour:23,afterMs:5*3600000,expired:false}])('uses the explicitly reviewed end at $hour:00',async({hour,afterMs,expired})=>{vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,17));const m=existing();delete m.preparation;m.source='calendar';m.startAtIso=new Date(2027,0,8,16).toISOString();m.endAtIso=new Date(2027,0,8,21).toISOString();h.calendar=[m];h.params={momentId:m.id};await mount();await act(async()=>button('Prepare').click());h.calendar=[{...m,endAtIso:new Date(2027,0,8,hour).toISOString()}];await mount();click('Review updated event');await act(async()=>vi.advanceTimersByTime(afterMs));expect(host.textContent?.includes('That Moment has ended')).toBe(expired);expect(!!host.querySelector('[aria-label="Moment"]')).toBe(!expired);expect(h.commit).not.toHaveBeenCalled();});
});

describe('A shortened source validity does not wait for acceptance',()=>{
 it('expires at an earlier known end even while the update review is pending',async()=>{vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,17));const m=existing();delete m.preparation;m.source='calendar';m.startAtIso=new Date(2027,0,8,16).toISOString();m.endAtIso=new Date(2027,0,8,21).toISOString();h.calendar=[m];h.params={momentId:m.id};await mount();await act(async()=>button('Prepare').click());h.calendar=[{...m,endAtIso:new Date(2027,0,8,18).toISOString()}];await mount();expect(host.textContent).toContain('Review updated event');await act(async()=>vi.advanceTimersByTime(3600001));expect(host.textContent).toContain('That Moment has ended');expect(host.querySelector('[aria-label="Moment"]')).toBeNull();expect(h.commit).not.toHaveBeenCalled();});
});

describe('Calendar completion during review',()=>{
 it('removes an unsealed candidate that became prepared in the shared layer',async()=>{const m=existing();delete m.preparation;m.source='calendar';h.calendar=[m];h.params={momentId:m.id};await mount();await act(async()=>button('Prepare').click());h.calendar=[{...m,preparedAtIso:new Date().toISOString()}];await mount();expect(host.textContent).toContain('no longer available');expect(host.querySelector('[aria-label="Moment"]')).toBeNull();expect(h.commit).not.toHaveBeenCalled();});
});

describe('travel during local-time review',()=>{
 it.each(['America/Los_Angeles','America/Lima'])('requires another review after changing from New York to %s during Seal',async(zone)=>{const prior=process.env.TZ;try{process.env.TZ='America/New_York';vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,17));await mount();field('Your moment','Team dinner today at 7:30 PM');click('Review my moment');click('Continue');click('Review & seal');const ring=host.querySelector('[aria-label="Hold to seal"]') as HTMLElement;act(()=>ring.dispatchEvent(new MouseEvent('mousedown',{bubbles:true,button:0})));process.env.TZ=zone;await act(async()=>vi.advanceTimersByTime(1400));expect(h.commit).not.toHaveBeenCalled();expect(host.textContent).toContain('Your time zone changed');expect(host.querySelector('[aria-label="Date · YYYY-MM-DD"]')).toBeTruthy();expect(host.querySelector('[aria-label="Time · HH:mm"]')).toBeTruthy();click('Continue');click('Review & seal');act(()=>(host.querySelector('[aria-label="Hold to seal"]') as HTMLElement).dispatchEvent(new MouseEvent('mousedown',{bubbles:true,button:0})));await act(async()=>vi.advanceTimersByTime(1400));expect(h.commit).toHaveBeenCalledTimes(1);expect(new Date(h.moments[0]!.startAtIso).getHours()).toBe(19);expect(h.moments[0]).not.toHaveProperty('timeZoneKey');}finally{if(prior===undefined)delete process.env.TZ;else process.env.TZ=prior;}});
 it('rechecks the timezone when a queued save begins',async()=>{const prior=process.env.TZ;try{process.env.TZ='America/New_York';vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,17));await mount();field('Your moment','Dinner today at 7:30 PM');click('Review my moment');click('Continue');click('Review & seal');h.beforeValidate=()=>{process.env.TZ='America/Los_Angeles';};act(()=>(host.querySelector('[aria-label="Hold to seal"]') as HTMLElement).dispatchEvent(new MouseEvent('mousedown',{bubbles:true,button:0})));await act(async()=>vi.advanceTimersByTime(1400));expect(h.commit).not.toHaveBeenCalled();expect(host.textContent).toContain('Your time zone changed');expect(host.textContent).not.toContain('Your plan is yours.');}finally{if(prior===undefined)delete process.env.TZ;else process.env.TZ=prior;}});
});

it('keeps an acknowledged saved instant unchanged when reopened in another timezone',async()=>{const prior=process.env.TZ;const m=existing();const original=m.startAtIso;try{process.env.TZ='America/Los_Angeles';h.moments=[m];await mount();expect(host.textContent).toContain('Go perform.');expect(h.moments[0]!.startAtIso).toBe(original);expect(h.commit).not.toHaveBeenCalled();}finally{if(prior===undefined)delete process.env.TZ;else process.env.TZ=prior;}});

describe('deleted member Moment invalidates the open preparation',()=>{
 it('leaves Quiet and clears private context and destination after deletion',async()=>{const m=existing();m.preparation!.lockedInAtIso=new Date().toISOString();m.safetyContext={mentionedAtIso:new Date().toISOString(),expiresAtIso:new Date(Date.now()+3600000).toISOString(),region:'test',policyVersion:'test'};h.moments=[m];await mount();expect(host.textContent).toContain('Phone down.');h.moments=[];await mount();expect(host.textContent).toContain('That Moment is no longer available');expect(host.textContent).not.toContain('Phone down.');expect(host.textContent).not.toContain('Hotel');expect((host.querySelector('[aria-label="Your moment"]') as HTMLTextAreaElement).value).toBe('');field('Your moment','I am driving');click('Review my moment');expect(host.textContent).toContain('HERE’S WHAT I HEARD');expect(host.textContent).not.toContain('AFORCE can’t assess');expect(h.commit).not.toHaveBeenCalled();});
 it('cancels a Seal hold for a deleted existing Moment',async()=>{vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,17));const m=existing();delete m.preparation;m.startAtIso=new Date(2027,0,8,19,30).toISOString();h.moments=[m];h.params={momentId:m.id};await mount();await act(async()=>button('Prepare').click());click('Continue');click('Review & seal');act(()=>(host.querySelector('[aria-label="Hold to seal"]') as HTMLElement).dispatchEvent(new MouseEvent('mousedown',{bubbles:true,button:0})));await act(async()=>vi.advanceTimersByTime(600));h.moments=[];await mount();await act(async()=>vi.advanceTimersByTime(1000));expect(h.commit).not.toHaveBeenCalled();expect(host.textContent).toContain('That Moment is no longer available');expect(host.querySelector('[aria-label="Hold to seal"]')).toBeNull();});
 it('does not revive a deleted candidate after a delayed Prepare acknowledgement',async()=>{const m=existing();delete m.preparation;h.moments=[m];h.params={momentId:m.id,proposal:'1'};await mount();let release!:()=>void;h.preference.mockImplementationOnce(()=>new Promise<void>(resolve=>{release=resolve;}));act(()=>button('Prepare').click());h.moments=[];await mount();await act(async()=>release());expect(host.textContent).toContain('That Moment is no longer available');expect(host.querySelector('[aria-label="Moment"]')).toBeNull();expect(h.commit).not.toHaveBeenCalled();});
 it('preserves unrelated Moments when clearing the removed plan',async()=>{const m=existing();const other={...m,id:'other',title:'Work meeting'};h.moments=[m,other];h.params={momentId:m.id};await mount();h.moments=[other];await mount();expect(host.textContent).toContain('That Moment is no longer available');expect(h.moments).toEqual([other]);expect(h.commit).not.toHaveBeenCalled();});
 it('clears the stale view after an in-flight write rejects because of deletion',async()=>{const m=existing();h.moments=[m];await mount();let reject!:(err:Error)=>void;h.commit.mockImplementationOnce(()=>new Promise((_resolve,rejectWrite)=>{reject=rejectWrite;}));act(()=>button('Lock In').click());h.moments=[];await mount();await act(async()=>reject(new Error('Moment deleted')));expect(host.textContent).toContain('That Moment is no longer available');expect(host.textContent).not.toContain('Phone down.');expect(h.moments).toHaveLength(0);});
});

describe('typing takes over from voice',()=>{
 it('cancels a pending capture and enables review of the typed text',async()=>{h.voiceBusy=true;await mount();expect(button('Review my moment').getAttribute('aria-disabled')).toBe('true');const before=h.voiceCancel.mock.calls.length;field('Your moment','My edited dinner tomorrow at 7:30 PM');expect(h.voiceCancel.mock.calls.length).toBeGreaterThan(before);expect(h.voiceBusy).toBe(false);expect(button('Review my moment').getAttribute('aria-disabled')).not.toBe('true');click('Review my moment');expect((host.querySelector('[aria-label="Moment"]') as HTMLInputElement).value).toContain('My edited dinner');expect(h.commit).not.toHaveBeenCalled();});
 it('keeps subsequent typing intact without restarting voice',async()=>{await mount();field('Your moment','Dinner');field('Your moment','Dinner with Julius tomorrow at 7:30 PM');expect((host.querySelector('[aria-label="Your moment"]') as HTMLTextAreaElement).value).toBe('Dinner with Julius tomorrow at 7:30 PM');expect(h.commit).not.toHaveBeenCalled();});
});

describe('daytime preparation and timing revisions',()=>{
 it('uses the edited daytime throughout Plan, Lock In, Quiet and private Return',async()=>{vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,11));const m=existing();delete m.preparation;m.startAtIso=new Date(2027,0,8,20).toISOString();h.moments=[m];h.params={momentId:m.id};await mount();await act(async()=>button('Prepare').click());field('Moment','Pool party');const nightColor=getComputedStyle(button('Continue')).backgroundColor;field('Time · HH:mm','14:00');expect(getComputedStyle(button('Continue')).backgroundColor).not.toBe(nightColor);click('Continue');click('Review & seal');act(()=>(host.querySelector('[aria-label="Hold to seal"]') as HTMLElement).dispatchEvent(new MouseEvent('mousedown',{bubbles:true,button:0})));await act(async()=>vi.advanceTimersByTime(1400));expect(host.querySelector('[aria-label="Sun orb"]')).toBeTruthy();expect(new Date(h.moments[0]!.startAtIso).getHours()).toBe(14);await act(async()=>button('Lock In').click());expect(host.querySelector('[aria-label="Sun orb"]')).toBeTruthy();click('Heading back?');await act(async()=>button('Made it back ✓').click());expect(host.textContent).toContain('Enjoy the rest of your day.');expect(h.moments).toHaveLength(1);expect(h.moments[0]!.preparation!.returnedAtIso).toBeTruthy();});
 it('uses tonight rather than today for a fresh capture before dawn',async()=>{vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,1));await mount();expect(host.textContent).toContain('What would make tonight go well?');expect(host.textContent).not.toContain('What would make today go well?');});
 it('does not anchor next context to a normalized invalid date',async()=>{vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,11));const m=existing();delete m.preparation;m.startAtIso=new Date(2027,0,8,16).toISOString();h.moments=[m];await mount();field('Your moment','Dinner tomorrow at 7:30 PM');click('Review my moment');field('Date · YYYY-MM-DD','2027-02-30');expect(host.textContent).toContain('Team dinner');click('Continue');expect(host.textContent).toContain('That local date or time does not exist');expect(h.commit).not.toHaveBeenCalled();});
});

describe('voice availability is reflected in capture controls',()=>{
 it('has no inactive voice button when only typing is supported',async()=>{await mount();expect(host.querySelector('[aria-label="Speak your moment"]')).toBeNull();expect(host.textContent).toContain('Type your moment');field('Your moment','Dinner tomorrow at 7:30 PM');click('Review my moment');expect(host.textContent).toContain('HERE’S WHAT I HEARD');expect(h.commit).not.toHaveBeenCalled();});
 it('exposes the voice control only when recognition is supported',async()=>{h.voiceAvailable=true;await mount();expect(host.querySelector('[aria-label="Speak your moment"]')).toBeTruthy();expect(host.textContent).toContain('Tap to speak · or type');expect(host.querySelector('[aria-label="Your moment"]')).toBeTruthy();h.voiceAvailable=false;await mount();expect(host.querySelector('[aria-label="Speak your moment"]')).toBeNull();});
});

describe('shared terminal outcome updates an open screen',()=>{
 it('leaves Quiet when another shared surface acknowledges cancellation',async()=>{const m=existing();m.preparation!.lockedInAtIso=new Date().toISOString();h.moments=[m];await mount();expect(host.textContent).toContain('Phone down.');h.moments=[{...m,preparation:{...m.preparation!,transactionId:'external-cancel',cancelledAtIso:new Date().toISOString()}}];await mount();expect(host.textContent).toContain('Plan cancelled.');expect(host.textContent).not.toContain('Heading back?');expect(host.textContent).not.toContain('Made it back ✓');expect(h.commit).not.toHaveBeenCalled();});
 it('leaves an open Return screen when the shared Moment has already returned',async()=>{const m=existing();m.preparation!.lockedInAtIso=new Date().toISOString();h.moments=[m];await mount();click('Heading back?');h.moments=[{...m,preparation:{...m.preparation!,transactionId:'external-return',returnedAtIso:new Date().toISOString()}}];await mount();expect(host.textContent).toContain('Did it go the way you wanted?');expect(host.textContent).not.toContain('Made it back ✓');expect(h.commit).not.toHaveBeenCalled();});
});

it('offers an explicit typing action that focuses the field and cancels pending voice',async()=>{
 h.voiceAvailable=true;h.voiceBusy=true;await mount();const before=h.voiceCancel.mock.calls.length;click('Type instead');expect(h.voiceCancel.mock.calls.length).toBeGreaterThan(before);expect(h.voiceBusy).toBe(false);expect(document.activeElement).toBe(host.querySelector('[aria-label="Your moment"]'));field('Your moment','Typed QA dinner tomorrow at 8 PM');expect(button('Review my moment').getAttribute('aria-disabled')).not.toBe('true');click('Review my moment');expect(host.textContent).toContain('HERE’S WHAT I HEARD');expect(h.commit).not.toHaveBeenCalled();
});
describe('Confirmation window on the Seal view (spec v1.8.2 Parts 6.1, 8.1)',()=>{
 const reachSeal=async()=>{vi.useFakeTimers();vi.setSystemTime(new Date(2027,0,8,17));await mount();field('Your moment','Team dinner today at 7:30 PM');click('Review my moment');click('Continue');click('Review & seal');};
 const reply=async(text:string)=>{field('Or type it',text);await act(async()=>button('Reply').click());};
 // "Team dinner, today at 7:30 PM. Say 'seal it' to lock it in." is 13 words at 2.5 words/s.
 const finishReadBack=async()=>{await act(async()=>vi.advanceTimersByTime(5300));};
 const pressSeal=()=>act(()=>(host.querySelector('[aria-label="Hold to seal"]') as HTMLElement).dispatchEvent(new MouseEvent('mousedown',{bubbles:true,button:0})));
 it('reads the plan back with the window closed, and "seal it" before it opens does nothing (V1, V13, V14)',async()=>{await reachSeal();expect(host.textContent).toContain("Team dinner, today at 7:30 PM. Say 'seal it' to lock it in.");expect(host.textContent).toContain('Listening opens after the read-back.');await reply('seal it');expect(h.commit).not.toHaveBeenCalled();expect(host.textContent).toContain("Heard 'seal it' outside the window · nothing happened.");});
 it('opens window 1 after the read-back; "yes" only prompts; "seal it" seals once with a decision record; Undo returns it to awaiting seal (V2, V4, V13)',async()=>{await reachSeal();await finishReadBack();expect(host.textContent).toContain('Confirmation window 1 · open');expect(host.textContent).toContain("Listening for 'Seal it'");await reply('yes');expect(host.textContent).toContain("Say 'seal it' to confirm.");expect(h.commit).not.toHaveBeenCalled();await reply('seal it');expect(h.commit).toHaveBeenCalledTimes(1);expect(h.moments[0]!.preparation!.sealedBy).toEqual({method:'typed',window:1});expect(host.textContent).toContain('Go perform.');await act(async()=>button('Undo').click());expect(h.moments).toHaveLength(1);expect(h.moments[0]!.preparation!.sealedAtIso).toBe('');expect(h.moments[0]!.preparation!.sealedBy).toBeUndefined();expect(host.textContent).toContain('Seal undone · awaiting seal');expect(host.textContent).toContain('Only what you approve');});
 it('offers Undo only for the undo window',async()=>{await reachSeal();await finishReadBack();await reply('lock it in');expect(button('Undo')).toBeTruthy();await act(async()=>vi.advanceTimersByTime(5100));expect(()=>button('Undo')).toThrow();expect(h.moments[0]!.preparation!.sealedAtIso).not.toBe('');});
 it('closes after 7 seconds with nothing heard; only Hear it again reopens, as window 2 (V14)',async()=>{await reachSeal();await finishReadBack();await act(async()=>vi.advanceTimersByTime(7100));expect(host.textContent).toContain('Closed after 7 seconds · nothing heard');await reply('seal it');expect(h.commit).not.toHaveBeenCalled();expect(host.textContent).toContain('outside the window');click('Hear it again');expect(host.textContent).toContain('Listening opens after the read-back.');await finishReadBack();expect(host.textContent).toContain('Confirmation window 2 · open');});
 it('"make it 8 PM" rebuilds and reads back again without sealing (V3, V15)',async()=>{await reachSeal();await finishReadBack();await reply('make it 8 PM');expect(h.commit).not.toHaveBeenCalled();expect(host.textContent).toContain('Closed · you corrected the plan');expect(host.textContent).toContain("Team dinner, today at 8:00 PM. Say 'seal it' to lock it in.");expect(host.textContent).toContain('Listening opens after the read-back.');await finishReadBack();expect(host.textContent).toContain('Confirmation window 2 · open');});
 it('a negation cancels and nothing is saved (V2)',async()=>{await reachSeal();await finishReadBack();await reply('not yet');expect(host.textContent).toContain('Closed · you said no');expect(host.textContent).toContain('Nothing saved.');expect(h.commit).not.toHaveBeenCalled();});
 it('a question closes the window, gets an honest limit and a fresh read-back (Part 8.1.7)',async()=>{await reachSeal();await finishReadBack();await reply('What should I eat before?');expect(h.commit).not.toHaveBeenCalled();expect(host.textContent).toContain('Closed · you asked something else');expect(host.textContent).toContain('Your plan is still waiting for you to seal it.');await finishReadBack();expect(host.textContent).toContain('Confirmation window 2 · open');});
 it('hold to seal still works during the read-back and offers no voice Undo (Part 8.1.8)',async()=>{await reachSeal();pressSeal();await act(async()=>vi.advanceTimersByTime(1400));expect(h.commit).toHaveBeenCalledTimes(1);expect(h.moments[0]!.preparation!.sealedBy).toEqual({method:'hold'});expect(()=>button('Undo')).toThrow();});
});
